    "keys_yuki": [
      {"days": "weekday", "from": 0, "to": 14.5, "at": "entry_table_e1", "chance": "usually"},
      {"days": "weekday", "from": 14.5, "to": 16, "at": "OUT_OF_HOUSE", "chance": "sometimes"},
      {"days": "weekday", "from": 16, "to": 24, "at": "entry_table_e1", "chance": "usually"}
    ],
    "jacket_yuki": [
      {"days": "weekday", "from": 0, "to": 14.5, "at": "entry_floor_e1", "chance": "usually"},
      {"days": "weekday", "from": 14.5, "to": 16, "at": "OUT_OF_HOUSE", "chance": "sometimes"},
      {"days": "weekday", "from": 16, "to": 24, "at": "entry_floor_e1", "chance": "usually"}
    ],
    "sunglasses_yuki": [
      {"days": "weekday", "from": 0, "to": 14.5, "at": "entry_table_e1", "chance": "usually"},
      {"days": "weekday", "from": 14.5, "to": 16, "at": "OUT_OF_HOUSE", "chance": "rarely"},
      {"days": "weekday", "from": 16, "to": 24, "at": "entry_table_e1", "chance": "usually"}
    ],
    "water_bottle_yuki": [
      {"days": "weekday", "from": 0, "to": 19, "at": "dish_rack_k1", "chance": "usually"},
      {"days": "weekday", "from": 19, "to": 21, "at": "kitchen_table_k1", "chance": "usually"},
      {"days": "weekday", "from": 21, "to": 24, "at": "dish_rack_k1", "chance": "usually"}
    ]
  },
  "claims": [
    {"claim": "Yuki's keys are back at the entry table by 17:00 on a weekday", "target": "keys_yuki", "expect": "entry_table_e1", "days": "weekday", "from": 17, "to": 22},
    {"claim": "Yuki's keys are out of the house during her short afternoon errand", "target": "keys_yuki", "expect": "OUT_OF_HOUSE", "days": "weekday", "from": 14.5, "to": 16},
    {"claim": "Yuki's jacket is at the entry floor in the evening after she is home", "target": "jacket_yuki", "expect": "entry_floor_e1", "days": "weekday", "from": 17, "to": 22},
    {"claim": "Yuki's water bottle is at the dish rack before dinner", "target": "water_bottle_yuki", "expect": "dish_rack_k1", "days": "weekday", "from": 16, "to": 18.5}
  ]
